                count++;
                // BFS/DFS
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i,j});
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int r = cell[0];
                    int c = cell[1];
                    for (int k=0; k<8; k++) {
                        int nr = r + dx[k];
