        for (int j=0;j<cols;j++){
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(i,j,grid,visited,rows,cols);
            }
        }
    }
    return count;
}

private static void dfs(int i,int j,char[][] grid,boolean[][] visited,int rows,int cols){
    if(i<0||i>=rows||j<0||j>=cols) return;
    if(visited[i][j] || grid[i][j] != '@') return;
    visited[i][j] = true;
    int[] di = {-1,-1,-1,0,0,1,1,1};
    int[] dj = {-1,0,1,-1,1,-1,0,1};
    for(int k=0;k<8;k++){
        dfs(i+di[k], j+dj[k], grid, visited, rows, cols);
    }
}

