    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            if (mask == (1 << n) - 1) return 1;
            int val = memo[mask][last];
            if (val != -1) return val;
            int sum = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && can[last][next]) {
                    sum += dfs.applyAsInt(mask | (1 << next), next);
                }
            }
            memo[mask][last] = sum;
            return sum;
        }
    };
    int total = 0;
    for (int start = 0; start < n; start++) {
        total += dfs.applyAsInt(1 << start, start);
    }
    return total;
}

